 var mat=new Material(m.surfaces[0].sharedMaterial);mat.name="Jaw pain - imported hologram, artistic reconstruction";mat.SetTexture("_Hologram_Texture",tex);mat.SetColor("_Texture_Tint_Color",new Color(.16f,.78f,.45f,.84f));mat.SetColor("_Hologram_Color",new Color(.02f,.25f,.10f,.015f));mat.SetFloat("_Emission_Scale",1.25f);AssetDatabase.CreateAsset(mat,"Assets/Room2/Panopticon/Materials/JawPainReconstruction.mat");
